        tenantsData.push({ name: names[0], content: rawData.trim() });
    } else {
        const blocks = rawData.split(/基本信息[：:]/);
        for (let i = 1; i < blocks.length && i - 1 < names.length; i++) {
            tenantsData.push({ name: names[i - 1], content: '基本信息：' + blocks[i].trim() });
