        var btn = this;
        // 查找酒馆助手API（遍历parent链，兼容iframe嵌套）
        var getOrCreate = null, updateWB = null;
        var w = window;
        for (var depth = 0; depth < 5 && w; depth++) {
            if (typeof w.getOrCreateChatWorldbook === 'function') getOrCreate = w.getOrCreateChatWorldbook;
            if (typeof w.updateWorldbookWith === 'function') updateWB = w.updateWorldbookWith;
            if (getOrCreate && updateWB) break;
            try { w = w.parent; } catch(e) { break; }
            if (w === window) break;
        }
        if (getOrCreate && updateWB) {
            try {
                var loreName = await getOrCreate('current');
                if (!loreName) { alert('无法创建ChatLore'); return; }
                var successCount = 0;
                for (var i = 0; i < tenantsData.length; i++) {
                    var content = document.getElementById('tenant-content-' + i).textContent.trim();
