            roomPicker.classList.remove('active');
            return;
        }
        // 尝试从掌上公寓获取卧室列表
        var bedrooms = [];
        try { bedrooms = parent.getApartmentBedrooms ? parent.getApartmentBedrooms() : []; } catch(e) {}

        roomGrid.innerHTML = '';
        if (bedrooms.length > 0) {
            roomFallback.style.display = 'none';
            bedrooms.forEach(function(r, i) {
                var badgeClass = r.isEmpty ? 'badge-empty' : 'badge-occupied';
                var badgeText = r.isEmpty ? '✅ 空闲' : '🏠 ' + r.occupant;
                var card = document.createElement('div');
                card.className = 'room-card';
                card.dataset.key = r.key;
                card.dataset.occupant = r.isEmpty ? '' : r.occupant;
                card.innerHTML = '<div class="room-card-name">' + r.name + '</div>'
                    + '<div class="room-card-info">' + r.floor + ' · ' + r.position + '</div>'
                    + '<span class="room-card-badge ' + badgeClass + '">' + badgeText + '</span>';
                card.addEventListener('click', function() {
                    roomGrid.querySelectorAll('.room-card').forEach(function(c) { c.classList.remove('rc-selected'); });
                    card.classList.add('rc-selected');
                    selectedRoomKey = r.key;
                    selectedRoomOccupant = r.isEmpty ? '' : r.occupant;
                    confirmRoomBtn.classList.remove('disabled');
                    confirmRoomBtn.innerHTML = '<i class="fa fa-check"></i> 入住 → ' + r.name;
