        var message = '请让 ' + tenantNames + ' 正式入住「' + selectedRoomKey + '」。';
        if (selectedRoomOccupant) {
            message += '（该房间已有住户「' + selectedRoomOccupant + '」，新租客将合租，住户字段更新为「' + selectedRoomOccupant + '、新租客姓名」）';
        }
        if (typeof triggerSlash === 'function') {
            triggerSlash('/send ' + message.trim() + '|/trigger');
        } else {
            alert('模拟发送：\n' + message);
        }
        confirmRoomBtn.innerHTML = '<i class="fa fa-check"></i> ✅ 已提交';
        confirmRoomBtn.classList.add('disabled');
        confirmMoveInBtn.innerHTML = '<i class="fa fa-check"></i> ✅ 已安排入住';
        confirmMoveInBtn.classList.add('disabled');
    });
})();
</script>
