  </div>
  <div class="chat-content" id="chat-window">
    </div>

  <div id="chat-data" style="display: none;">$2</div>
</div>

<script>
  // 当整个页面加载完毕后，这个脚本才会运行
  window.onload = function() {
    // 找到存放原始聊天记录的隐藏div
    const rawDataElement = document.getElementById('chat-data');
    // 找到我们要填充内容的聊天窗口
    const chatWindow = document.getElementById('chat-window');

    // 如果没找到数据，就什么也不做
    if (!rawDataElement) return;

    // 读取原始文本数据，并按行分割成一个数组
    const lines = rawDataElement.textContent.trim().split('\n');

    // 遍历每一行对话
    lines.forEach(line => {
      // 用正则表达式匹配“名字: 消息”的格式
      const match = line.match(/^([^:]+):(.*)$/);

      // 如果匹配成功
      if (match) {
        const senderName = match[1].trim();
        const messageText = match[2].trim();

        // --- 开始像搭积木一样，创建HTML元素 ---
        const bubble = document.createElement('div');
        bubble.className = 'message-bubble';

        const sender = document.createElement('div');
        sender.className = 'sender-name';
        sender.textContent = senderName;

        const message = document.createElement('div');
        message.className = 'message-content';
        message.textContent = messageText;

        // 把“名字”和“消息”组装进“气泡”里
        bubble.appendChild(sender);
        bubble.appendChild(message);

        // 把完整的“气泡”放进聊天窗口里
        chatWindow.appendChild(bubble);
      }
    });
  };
</script>

</body>
</html>
